+import fs from 'node:fs';
+import path from 'node:path';
+import { createHash, createHmac, timingSafeEqual, sign, verify, randomUUID, createPublicKey } from 'node:crypto';
+
+export const digest = value => `sha256:${createHash('sha256').update(JSON.stringify(value)).digest('hex')}`;
+const fail = message => { throw new Error(message); };
+const object = x => x !== null && typeof x === 'object' && !Array.isArray(x);
+const exact = (value, keys) => {
+  if (!object(value) || Object.keys(value).some(k => !keys.includes(k)) || keys.some(k => !(k in value))) fail('Unexpected or missing protocol fields');
+};
+const text = x => typeof x === 'string' && x.length > 0 && x === x.trim();
+const hash = x => /^sha256:[a-f0-9]{64}$/.test(x);
+const id = x => /^[a-zA-Z0-9_-]{1,100}$/.test(x);
+const read = file => JSON.parse(fs.readFileSync(file, 'utf8'));
+function privateRoot(root) {
+  if(!root||!path.isAbsolute(root))fail('Date broker root must be absolute');
+  const st=fs.lstatSync(root);
+  if(!st.isDirectory()||(st.mode&0o077)!==0||(process.getuid&&st.uid!==process.getuid()))fail('Date broker root must be an owner-only directory');
+}
+function atomic(file, value) {
+  const tmp = `${file}.${randomUUID()}.tmp`;
+  fs.writeFileSync(tmp, `${JSON.stringify(value, null, 2)}\n`, { mode: 0o600, flag: 'wx' });
+  fs.renameSync(tmp, file);
+}
+const signed = (payload, privateKey) => ({ payload, signature: sign(null, Buffer.from(JSON.stringify(payload)), privateKey).toString('base64url') });
+function verified(document, publicKey) {
+  exact(document, ['payload', 'signature']);
+  if (!verify(null, Buffer.from(JSON.stringify(document.payload)), publicKey, Buffer.from(document.signature, 'base64url'))) fail('Invalid host admission signature');
+  return document.payload;
+}
+const jobDirectory = (root, admissionId) => {
+  if (!id(admissionId)) fail('Invalid admission ID');
+  return path.join(root, admissionId);
+};
+function validateEnvelope(a, artifact) {
+  exact(artifact,['type','generationId','worker','contextId','phase','packetHash','phaseHash','result']);
+  for(const [k,expected] of Object.entries({type:a.artifactType,generationId:a.generationId,worker:a.worker,contextId:a.contextId,phase:a.phase,packetHash:a.packetHash,phaseHash:a.phaseHash}))if(artifact[k]!==expected)fail(`Wrong artifact ${k}`);
+  const r=artifact.result,identityField=a.phase==='repair'?'author':'reviewer';
+  if(!object(r)||r.sourceHash!==a.sourceHash||r.extractionHash!==a.extractionHash)fail('Wrong result hashes');
+  if((a.phase!=='repair'&&r.jobId!==a.jobId)||!object(r[identityField])||r[identityField].agentId!==a.contextId||!text(r[identityField].name)||(a.phase!=='repair'&&r.reviewer.independentOfExtractor!==true))fail('Wrong actual result role/context');
+  if((a.phase==='repair'&&'reviewer'in r)||(a.phase!=='repair'&&'author'in r))fail('Mixed author/reviewer payload');
+  if(Buffer.byteLength(JSON.stringify(r))>a.maxBytes)fail('Result exceeds original job ceiling');
+  return r;
+}
+export function checkAdmission(a) {
+  exact(a, ['version','admissionId','hostSessionId','queueWorker','generationId','book','chapter','jobKey','jobId','phase','artifactType','worker','contextId','extractorContextIds','repairContextIds','sourceHash','extractionHash','packetHash','phaseHash','maxBytes','expiresAt','input']);
+  if (a.version !== 1 || !id(a.admissionId) || !id(a.hostSessionId) || !text(a.queueWorker) || !text(a.generationId) || !/^[a-z0-9_-]+$/.test(a.book) || !/^\d{3}$/.test(a.chapter) || !text(a.jobKey) || !text(a.jobId)) fail('Invalid admission scope');
+  if (!/^grokbot-[a-z0-9][a-z0-9-]{0,47}$/.test(a.worker) || !text(a.contextId)) fail('Invalid worker/context');
+  if (!['audit','reaudit','repair'].includes(a.phase) || a.artifactType !== (a.phase === 'repair' ? 'date-repair' : 'date-review')) fail('Wrong date phase/type');
+  if (![a.extractorContextIds,a.repairContextIds].every(xs => Array.isArray(xs) && xs.every(text))) fail('Explicit independent-context exclusions are required');
+  if (a.phase !== 'repair' && [...a.extractorContextIds,...a.repairContextIds].includes(a.contextId)) fail('Reviewer context is extractor or repair author');
+  if (![a.sourceHash,a.extractionHash,a.packetHash,a.phaseHash].every(hash) || !object(a.input) || a.input.sourceHash !== a.sourceHash || a.input.extractionHash !== a.extractionHash || digest(a.input) !== a.packetHash) fail('Invalid sealed packet hashes');
+  if (a.phaseHash !== digest({ phase:a.phase, artifactType:a.artifactType, jobKey:a.jobKey, jobId:a.jobId })) fail('Invalid phase hash');
+  if (!Number.isSafeInteger(a.maxBytes) || a.maxBytes < 1 || Buffer.byteLength(JSON.stringify(a.input)) > a.maxBytes || !Number.isFinite(Date.parse(a.expiresAt))) fail('Invalid original job ceiling/expiry');
+  if (a.phase !== 'repair' && a.input.id !== a.jobId) fail('Wrong sealed review job');
+  return a;
+}
+
+// Called ONLY by the existing host date worker, while its shared-pool slot is held.
+// Ed25519 private key is host-only; the MCP service needs only the public key.
+export function admitDateTask({ root, admission, privateKey }) {
+  checkAdmission(admission);
+  fs.mkdirSync(root, { recursive:true, mode:0o700 });
+  privateRoot(root);
+  for(const name of fs.readdirSync(root)) {
+    if(name===admission.admissionId||!fs.statSync(path.join(root,name)).isDirectory())continue;
+    const file=path.join(root,name,'admission.json');
+    if(!fs.existsSync(file))continue;
+    const old=checkAdmission(verified(read(file),createPublicKey(privateKey)));
+    if(old.worker!==admission.worker&&old.contextId!==admission.contextId)continue;
+    const state=path.join(root,name,'host-result.json');
+    const completion=fs.existsSync(state)?verified(read(state),createPublicKey(privateKey)):null;
+    if(completion&&completion.admissionHash!==digest(old))fail('Altered retained completion');
+    if(!completion||!['host-accepted','host-rejected'].includes(completion.status))fail('Worker/context has sticky unfinished date admission');
+  }
+  const dir = jobDirectory(root, admission.admissionId);
+  fs.mkdirSync(dir, { recursive:true, mode:0o700 });
+  const file = path.join(dir,'admission.json');
+  if (fs.existsSync(file)) {
+    if (JSON.stringify(verified(read(file),createPublicKey(privateKey))) !== JSON.stringify(admission)) fail('Retained admission changed');
+  } else fs.writeFileSync(file, `${JSON.stringify(signed(admission, privateKey),null,2)}\n`, {flag:'wx',mode:0o600});
+  return dir;
+}
+export function closeDateTask({ root, admission, privateKey, status, reason }) {
+  if (!['host-waiting','host-accepted','host-rejected','host-interrupted'].includes(status)) fail('Invalid host completion');
+  const document=signed({admissionId:admission.admissionId,admissionHash:digest(admission),status,reason},privateKey);
+  const dir=jobDirectory(root,admission.admissionId);
+  fs.writeFileSync(path.join(dir,`host-event-${randomUUID()}.json`),JSON.stringify(document,null,2)+'\n',{flag:'wx',mode:0o600});
+  atomic(path.join(dir,'host-result.json'),document);
+}
+
+export class DateArtifactTransport {
+  constructor({ root, publicKey, claimSecret, now = () => Date.now() }) {
+    if (!root || !path.isAbsolute(root) || !publicKey || !claimSecret || claimSecret.length < 32) fail('Date transport requires explicit root/public key/signing configuration');
+    Object.assign(this,{root,publicKey,claimSecret,now});
+    privateRoot(root);
+  }
+  admission(admissionId, { allowClosed=false } = {}) {
+    const dir=jobDirectory(this.root,admissionId);
+    const a=checkAdmission(verified(read(path.join(dir,'admission.json')),this.publicKey));
+    if (a.admissionId!==admissionId) fail('Admission path/scope mismatch');
+    const closed=path.join(dir,'host-result.json');
+    if (fs.existsSync(closed)) {
+      const c=verified(read(closed),this.publicKey);
+      if(c.admissionHash!==digest(a)||c.admissionId!==a.admissionId)fail('Altered host completion');
+      if(!allowClosed && c.status!=='host-waiting')fail(`Date admission is ${c.status}`);
+    }
+    if (!allowClosed && this.now() >= Date.parse(a.expiresAt)) fail('Expired host date admission; preserve and resume through host');
+    return a;
+  }
+  token(a) {
+    const encoded=Buffer.from(JSON.stringify({type:'date',admissionId:a.admissionId,admissionHash:digest(a)})).toString('base64url');
+    return `date1.${encoded}.${createHmac('sha256',this.claimSecret).update(`date1.${encoded}`).digest('base64url')}`;
+  }
+  fromToken(token, {allowClosed=false}={}) {
+    const [prefix,encoded,sig,extra]=String(token).split('.');
+    if(prefix!=='date1'||!encoded||!sig||extra)fail('Wrong date token');
+    const supplied=Buffer.from(sig,'base64url'),expected=createHmac('sha256',this.claimSecret).update(`date1.${encoded}`).digest();
+    if(supplied.length!==expected.length||!timingSafeEqual(supplied,expected))fail('Invalid date token signature');
+    const p=JSON.parse(Buffer.from(encoded,'base64url').toString());
+    exact(p,['type','admissionId','admissionHash']);
+    const a=this.admission(p.admissionId,{allowClosed});
+    if(p.type!=='date'||p.admissionHash!==digest(a))fail('Stale date generation/packet/worker/phase');
+    return a;
+  }
+  resume({type,worker,contextId,admissionId}) {
+    const a=this.admission(admissionId);
+    if(type!=='date'||worker!==a.worker||contextId!==a.contextId)fail('Wrong admitted worker/context');
+    return {type:'date',worker,contextId,admissionId,phase:a.phase,artifactType:a.artifactType,jobId:a.jobId,claimToken:this.token(a),chunks:[{id:a.admissionId}],instructions:'Return only this sealed date artifact. The host owns validation and publication; this transport cannot approve dates or launch inference.'};
+  }
+  get({claimToken,chunkId}) {
+    const a=this.fromToken(claimToken);
+    if(chunkId!==a.admissionId)fail('Wrong admitted chunk');
+    return {type:'date',admissionId:a.admissionId,worker:a.worker,contextId:a.contextId,generationId:a.generationId,phase:a.phase,artifactType:a.artifactType,packetHash:a.packetHash,phaseHash:a.phaseHash,input:a.input,instructions:'Use the actual assigned context identity. Return the full JSON artifact in a typed date envelope; transport acceptance is not historical approval.'};
+  }
+  submit({claimToken,chunkId,artifact}) {
+    const a=this.fromToken(claimToken),dir=jobDirectory(this.root,a.admissionId);
+    // Preserve every attempted payload before rejecting semantic protocol defects.
+    const capture={receivedAt:new Date(this.now()).toISOString(),artifact};
+    fs.writeFileSync(path.join(dir,`capture-${randomUUID()}.json`),JSON.stringify(capture,null,2)+'\n',{flag:'wx',mode:0o600});
+    if(chunkId!==a.admissionId)fail('Wrong admitted chunk');
+    const r=validateEnvelope(a,artifact);
+    const resultFile=path.join(dir,'result.json'),saved={admissionHash:digest(a),artifact};
+    if(fs.existsSync(resultFile)) {if(digest(read(resultFile))!==digest(saved))fail('Conflicting result; preserve capture and ask host to retry');}
+    else {
+      const tmp=path.join(dir,`result-${randomUUID()}.tmp`);
+      fs.writeFileSync(tmp,JSON.stringify(saved,null,2)+'\n',{flag:'wx',mode:0o600});
+      try{fs.linkSync(tmp,resultFile);}catch(error){if(error.code!=='EEXIST'||digest(read(resultFile))!==digest(saved))throw error;}
+      finally{fs.unlinkSync(tmp);}
+    }
+    return {type:'date',captured:true,approved:false,sha256:digest(r),next:'Host must run complete date validation; finalize returns only a capture receipt.'};
+  }
+  finalize({claimToken}) {
+    const a=this.fromToken(claimToken,{allowClosed:true}),dir=jobDirectory(this.root,a.admissionId),file=path.join(dir,'result.json');
+    if(!fs.existsSync(file))fail('Missing date result');
+    const saved=read(file);if(saved.admissionHash!==digest(a))fail('Stale captured date result');
+    validateEnvelope(a,saved.artifact);
+    return {type:'date',captured:true,approved:false,published:false,admissionId:a.admissionId,sha256:digest(saved.artifact.result)};
+  }
+  status({type,worker,contextId,admissionId}) {
+    if(type!=='date')fail('Wrong date status type');
+    const a=this.admission(admissionId,{allowClosed:true});
+    if(a.worker!==worker||a.contextId!==contextId)fail('Wrong admitted worker/context');
+    return {type:'date',worker,contextId,admissionId,phase:a.phase,captured:fs.existsSync(path.join(jobDirectory(this.root,admissionId),'result.json')),approved:false};
+  }
+}
+
+// No second executor/pool: runDateWorkflow already calls this worker inside
