+// The five operations remain unchanged. Extraction uses its existing live
+// implementation; date mode serves ONLY a host-signed, pre-admitted task.
+export function createTypedGrokbotBridge({ extraction, dates }) {
+  const only=(args,required,optional=[])=>{
+    if(!args||typeof args!=='object'||Array.isArray(args)||required.some(k=>!(k in args))||Object.keys(args).some(k=>![...required,...optional].includes(k)))throw new Error('Mixed, missing or unsupported operation fields');
+  };
+  const call=(operation,args)=>{
+    const type=args?.type??'extraction';
+    if(!['extraction','date'].includes(type))throw new Error('Unsupported artifact protocol');
+    if(type==='date') {
+      if(operation==='resumeOrClaim'||operation==='status')only(args,['type','worker','contextId','admissionId']);
+      if(operation==='getChunk')only(args,['type','claimToken','chunkId']);
+      if(operation==='submitChunk')only(args,['type','claimToken','chunkId','artifact']);
+      if(operation==='finalizeChapter')only(args,['type','claimToken']);
+      const method={resumeOrClaim:'resume',getChunk:'get',submitChunk:'submit',finalizeChapter:'finalize',status:'status'}[operation];
+      if(!method)throw new Error('Unsupported operation');
+      return dates()[method](args);
+    }
+    if(String(args?.claimToken).startsWith('date1.'))throw new Error('Date token requires explicit date protocol');
+    if(operation==='resumeOrClaim')only(args,['worker'],['type','book','chapter']);
